arguments.new_str:
class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: empty env vars are no longer treated as unset.
        // Previously GetEnvironmentVariable("MY_FLAG") returned null for export MY_FLAG="".
        // Now it correctly returns "" (empty string). Use HasKey-style check to
        // distinguish "not set" (null) from "explicitly empty" ("").
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (val == null)
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
        // This now works correctly on .NET 9 — no code change needed here because
        // the existing null check already distinguishes "not set" from "empty".
        // Previously this was BROKEN: empty vars returned null, making it impossible
        // to tell them apart. The .NET 9 fix is the desired behavior.
    }
}

