using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9 breaking change: ZipArchiveEntry now respects the UTF-8 flag in
        // the entry header. When creating entries with non-ASCII names, .NET 9 sets
        // the UTF-8 bit flag, so compliant readers will decode as UTF-8.
        // Our legacy Java system reads filenames in Shift-JIS, so we must use the
        // ZipFile.Open overload that accepts an explicit encoding to suppress the
        // UTF-8 flag and encode entry names in Shift-JIS instead.
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
        var shiftJis = Encoding.GetEncoding("Shift-JIS");
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create, shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

